using System;using System.Drawing;using System.Linq;using System.Windows.Forms;using Microsoft.Win32;
namespace BeamScheduleFormatter {
static class DesktopAppearance {
 internal static string StoragePath=AppearancePreferences.PathName;internal static Func<bool> ReadSystemLight=SystemUsesLight;
 static bool initialized;static Form dispatcher;static AppearanceMode mode=AppearanceMode.System;static DesktopPalette palette=new DesktopPalette(false);
 public static DesktopPalette Palette{get{return ReportPaperScope.Active?ReportPaperScope.Palette:palette;}}public static AppearanceMode Mode{get{return mode;}}public static string Warning{get;private set;}
 public static event Action Changed;
 public static void Initialize(){if(initialized)return;initialized=true;try{mode=AppearancePreferences.Read(StoragePath);}catch(Exception ex){Warning=ex.Message;mode=AppearanceMode.System;}palette=new DesktopPalette(AppearancePreferences.ResolveDark(mode,ReadSystemLight()));try{SystemEvents.UserPreferenceChanged+=SystemChanged;Application.ApplicationExit+=(s,e)=>{SystemEvents.UserPreferenceChanged-=SystemChanged;dispatcher=null;};}catch{/* Older/offline Windows sessions can still use explicit Light/Dark. */}}
 public static void Attach(Form form){Initialize();dispatcher=form;}
 static bool SystemUsesLight(){try{using(var key=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize")){object value=key==null?null:key.GetValue("AppsUseLightTheme");return value==null||Convert.ToInt32(value)!=0;}}catch{return true;}}
 public static void Select(AppearanceMode selected){AppearancePreferences.Write(StoragePath,selected);mode=selected;Warning=null;ApplyResolved();}
 static void SystemChanged(object sender,UserPreferenceChangedEventArgs args){var form=dispatcher;if(mode!=AppearanceMode.System||form==null||form.IsDisposed||!form.IsHandleCreated)return;try{form.BeginInvoke((Action)delegate{RefreshSystemTheme();});}catch(InvalidOperationException){} }
 internal static void RefreshSystemTheme(){if(mode==AppearanceMode.System)ApplyResolved();}
 static void ApplyResolved(){var next=new DesktopPalette(AppearancePreferences.ResolveDark(mode,ReadSystemLight()));var previous=palette;palette=next;if(previous.Dark!=next.Dark){foreach(var form in Application.OpenForms.Cast<Form>().ToArray())if(!form.IsDisposed)PowTheme.Refresh(form,previous);}if(Changed!=null)Changed();}
 public static void ShowSettings(IWin32Window owner){using(var form=new Form{Text="Workspace settings",Width=540,Height=440,MinimumSize=new Size(430,400),StartPosition=FormStartPosition.CenterParent,MaximizeBox=false,MinimizeBox=false}){AppBrand.Apply(form);var body=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(22),AutoScroll=true};body.Controls.Add(new Label{Text="Appearance",AutoSize=true,Font=PremiumControls.TitleFont});body.Controls.Add(new Label{Text="Choose how DTCE Tool Kit looks on this computer.",AutoSize=true,Margin=new Padding(3,8,3,10)});var choice=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=350};choice.Items.AddRange(new object[]{"Use system settings","Light","Dark"});choice.SelectedIndex=(int)mode;body.Controls.Add(choice);var note=new Label{AutoSize=true,MaximumSize=new Size(430,0),Margin=new Padding(3,12,3,6),Text=Warning??"Saved for this Windows account. The choice remains after app updates."};body.Controls.Add(note);choice.SelectedIndexChanged+=(s,e)=>{try{Select((AppearanceMode)choice.SelectedIndex);note.ForeColor=PowTheme.Muted;note.Text="Appearance saved.";}catch(Exception ex){note.ForeColor=Color.Firebrick;note.Text="Could not save appearance: "+ex.Message;}};body.Controls.Add(new Label{Text="Horizontal scroll",AutoSize=true,Font=PremiumControls.TitleFont,Margin=new Padding(3,16,3,0)});body.Controls.Add(new Label{Text="Tilt wheel / touchpad side scroll and Shift + mouse wheel, in tables and panels.",AutoSize=true,MaximumSize=new Size(430,0),Margin=new Padding(3,6,3,8)});var hs=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=350};hs.Items.AddRange(new object[]{"Normal (wheel down / tilt right = scroll right)","Reversed (wheel down / tilt right = scroll left)"});hs.SelectedIndex=HorizontalWheel.Reversed?1:0;hs.SelectedIndexChanged+=(s,e)=>{try{AppearancePreferences.WriteReversedScroll(StoragePath,hs.SelectedIndex==1);HorizontalWheel.Reversed=hs.SelectedIndex==1;note.ForeColor=PowTheme.Muted;note.Text="Horizontal scroll saved.";}catch(Exception ex){note.ForeColor=Color.Firebrick;note.Text="Could not save: "+ex.Message;}};body.Controls.Add(hs);var close=new Button{Text="Done",AutoSize=true,DialogResult=DialogResult.OK,Margin=new Padding(3,10,3,3)};body.Controls.Add(close);form.AcceptButton=close;form.CancelButton=close;form.Controls.Add(body);PowTheme.Apply(form);form.ShowDialog(owner);}}
}
}
